  void RefreshProblems(){if(problemPage==null||refreshingProblems)return;refreshingProblems=true;try{visibleProblems.Clear();foreach(var row in rows){if(row.Installed!=null&&row.Installed.retained)AddProblem(row,"RetainedState","RetainedHelp",string.Join(Environment.NewLine,row.Installed.files.Select(f=>f.target+" · "+f.hash)));AddProblem(row,"ConflictState","ConflictHelp",row.Conflict);AddProblem(row,"TargetUnavailable","CheckTargetHelp",row.TargetIssue);AddProblem(row,"TargetUnavailable","CheckTargetHelp",row.ServerIssue);AddProblem(row,"OperationFailed","RetryHelp",RowError(row),"ErrorLog");if(row.Package!=null)AddProblem(row,"MetadataIgnored","MetadataHelp",row.Package.MetadataIssue);}
