   problemGrid.Rows.Clear();foreach(var issue in visibleProblems){var row=rows.FirstOrDefault(r=>RowId(r)==issue.ModId);if(row==null&&issue.Folder!=null)row=rows.FirstOrDefault(r=>r.Package!=null&&Data.Same(r.Package.Folder,issue.Folder));string name=row==null?issue.ModId??(issue.Folder==null?L.Get("ManagerIssue"):Path.GetFileName(issue.Folder)):RawName(row);if(row!=null&&issue.ModId==null)issue.ModId=RowId(row);int i=problemGrid.Rows.Add(name,L.Get(issue.Kind),L.Get(issue.SummaryKey)+Environment.NewLine+L.Get(issue.RemedyKey));problemGrid.Rows[i].Cells[1].Style.ForeColor=issue.Kind=="ErrorLog"?Themes.Current.Error:Themes.Current.Warning;problemGrid.Rows[i].Cells[0].ToolTipText=(issue.ModId??"")+Environment.NewLine+issue.Folder;}
   problemInfo.Text=visibleProblems.Count==0?L.Get("NoProblems"):string.Format(L.Get("ProblemCount"),visibleProblems.Count);((DataGridViewButtonColumn)problemGrid.Columns[3]).Text=L.Get("ViewSolution");}finally{refreshingProblems=false;}}
  void ShowProblem(int index){if(index<0||index>=visibleProblems.Count)return;var item=visibleProblems[index];var row=rows.FirstOrDefault(r=>RowId(r)==item.ModId);string name=row==null?item.ModId??L.Get("ManagerIssue"):RawName(row);using(var dialog=CreateResultDialog(name+Environment.NewLine+L.Get(item.SummaryKey),L.Get(item.RemedyKey)+(row==null?"":Environment.NewLine+"Workshop ID: "+WorkshopIdFor(row)),new List<string>(),item.Details+Environment.NewLine+item.Folder)){var buttons=FindControls(dialog).OfType<FlowLayoutPanel>().Last();var related=new ModernButton{Text=L.Get("RelatedActivity"),AutoSize=true};related.Click+=delegate{activitySearch.Text=item.ModId??item.Folder??"";tabs.SelectedIndex=2;dialog.Close();};buttons.Controls.Add(related);Theme(dialog);dialog.ShowDialog(this);}}
