  void ConfigureSelectionHeader(DataGridView view){view.Columns[0].HeaderCell.Style.Alignment=DataGridViewContentAlignment.MiddleCenter;view.Columns[0].DefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleCenter;view.CellPainting+=delegate(object sender,DataGridViewCellPaintingEventArgs e){if(e.ColumnIndex!=0)return;e.PaintBackground(e.ClipBounds,false);string value=e.RowIndex==-1?view.Columns[0].HeaderText:Convert.ToString(view.Rows[e.RowIndex].Cells[0].Value);if(value=="True"||value=="Checked")value="☑";else if(value=="Indeterminate")value="◩";int scale=Math.Max(13,(int)(14*CreateGraphicsDpi()/96f));var box=new Rectangle(e.CellBounds.X+(e.CellBounds.Width-scale)/2,e.CellBounds.Y+(e.CellBounds.Height-scale)/2,scale,scale);using(var b=new SolidBrush(Themes.Current.Surface))e.Graphics.FillRectangle(b,box);using(var pen=new Pen(Themes.Current.Accent,1.5f)){e.Graphics.DrawRectangle(pen,box);if(value=="☑"){e.Graphics.DrawLines(pen,new[]{new Point(box.Left+3,box.Top+7),new Point(box.Left+6,box.Bottom-3),new Point(box.Right-2,box.Top+3)});}else if(value=="◩")e.Graphics.DrawLine(pen,box.Left+3,box.Top+scale/2,box.Right-3,box.Top+scale/2);}e.Handled=true;};}
